<!doctype html>
<html lang="sw">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ramani Majengo | AI House Planner Tanzania</title>
<style>
:root{--bg:#07111f;--panel:#0e1b2d;--panel2:#12243a;--line:#29425f;--text:#edf5ff;--muted:#9fb2c8;--accent:#35d0ba;--accent2:#f4b942;--danger:#ff6b6b;--paper:#fff}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,Segoe UI,Arial,sans-serif;background:linear-gradient(135deg,#06101c,#0b1728 55%,#07111f);color:var(--text)}button,input,select,textarea{font:inherit}button{cursor:pointer}.wrap{max-width:1400px;margin:auto;padding:22px}.top{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px 0 26px}.brand{font-weight:900;font-size:25px;letter-spacing:.3px}.brand span{color:var(--accent)}.badge{border:1px solid var(--line);padding:8px 12px;border-radius:999px;color:var(--muted);font-size:13px}.hero{display:grid;grid-template-columns:1.25fr .75fr;gap:24px;align-items:stretch}.heroCard,.panel{background:rgba(14,27,45,.94);border:1px solid var(--line);border-radius:20px;box-shadow:0 18px 50px rgba(0,0,0,.25)}.heroCard{padding:34px}.hero h1{font-size:clamp(34px,5vw,64px);line-height:1.02;margin:0 0 18px}.hero h1 em{font-style:normal;color:var(--accent)}.hero p{color:var(--muted);font-size:17px;line-height:1.65;max-width:760px}.heroVisual{min-height:330px;display:flex;align-items:center;justify-content:center;padding:22px;overflow:hidden}.house3d{width:100%;height:270px;position:relative}.house3d .roof{position:absolute;width:65%;height:115px;left:17%;top:35px;background:#1e354e;transform:skewY(-18deg) rotate(0deg);border:2px solid #4a6684}.house3d .wall{position:absolute;width:65%;height:120px;left:17%;top:112px;background:#d8c9a8;border:2px solid #6e7c88}.house3d .side{position:absolute;width:23%;height:120px;left:59.5%;top:112px;background:#b9a98a;transform:skewY(25deg);transform-origin:left top;border:2px solid #6e7c88}.window{position:absolute;width:62px;height:52px;background:#79c9d5;border:5px solid #40546a;top:142px;left:27%}.door{position:absolute;width:48px;height:78px;background:#6d4930;border:4px solid #3b2b21;top:154px;left:47%}.form{margin-top:24px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}label{font-size:13px;color:#b9c9da;font-weight:700}input,select,textarea{width:100%;background:#091625;border:1px solid #2a405b;color:var(--text);padding:12px 13px;border-radius:11px;outline:none}textarea{min-height:95px;resize:vertical}input:focus,select:focus,textarea:focus{border-color:var(--accent)}.rooms{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.check{display:flex;align-items:center;gap:8px;color:#dce7f2;font-size:14px}.check input{width:auto}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.primary{border:0;border-radius:12px;background:var(--accent);color:#03221d;font-weight:900;padding:13px 18px}.secondary{border:1px solid var(--line);border-radius:12px;background:#0b1829;color:var(--text);padding:13px 18px}.layout{margin-top:24px;display:grid;grid-template-columns:1fr;gap:20px}.panel{padding:20px}.panel h2{margin:0 0 5px}.sub{color:var(--muted);font-size:14px}.status{margin:12px 0;padding:11px;border-radius:10px;background:#0a1727;color:#b9c9da;border:1px solid var(--line);display:none}.status.show{display:block}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.tab{background:#0a1727;border:1px solid var(--line);color:#cfe0f0;border-radius:10px;padding:9px 12px}.tab.active{border-color:var(--accent);color:var(--accent)}.canvas{background:#eef2f5;border-radius:14px;padding:12px;overflow:auto}.canvas svg{display:block;width:100%;min-width:760px;height:auto;background:white}.viewGrid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.info{background:#091625;border:1px solid var(--line);border-radius:13px;padding:14px}.info strong{display:block;margin-bottom:6px}.info p{color:var(--muted);line-height:1.55;margin:0}.notice{border-left:4px solid var(--accent2);background:#19180f;color:#eadfbf;padding:13px;border-radius:9px;line-height:1.55;margin-top:15px}.printBtn{float:right}.footer{color:#8195aa;text-align:center;padding:30px 0 15px;font-size:13px}.roomLine{display:flex;gap:8px;align-items:center}.roomLine input{flex:1}.remove{background:#261519;color:#ff9c9c;border:1px solid #60313a;border-radius:9px;padding:10px}.small{font-size:12px;color:#8ea2b8}
@media(max-width:900px){.hero{grid-template-columns:1fr}.viewGrid{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.rooms{grid-template-columns:1fr}.heroVisual{min-height:280px}}
@media print{body{background:#fff;color:#000}.top,.hero,.form,.tabs,.actions,.notice,.footer,.sub,.status{display:none!important}.wrap,.layout,.panel{padding:0;margin:0;max-width:none;border:0;box-shadow:none;background:#fff}.canvas{padding:0}.canvas svg{min-width:0;width:100%}.printBtn{display:none!important}}
</style>
</head>
<body>
<div class="wrap">
  <div class="top"><div class="brand">RAMANI<span> MAJENGO</span></div><div class="badge">AI House Planner • Tanzania</div></div>
  <section class="hero">
    <div class="heroCard">
      <h1>Geuza wazo la nyumba kuwa <em>ramani</em>.</h1>
      <p>Ingiza mahitaji ya mteja: ukubwa wa kiwanja, vyumba, vipimo, mwelekeo na mahitaji maalum. Mfumo unatengeneza <b>mpangilio wa awali wenye vipimo</b>, muonekano wa nyumba na maelezo ya kila chumba.</p>
      <div class="notice">Hii ni design/planning assistant. Ramani ya mwisho ya ujenzi lazima ikaguliwe na mtaalamu mwenye sifa na kuendana na kanuni za eneo, udongo, structure, drainage na vibali husika.</div>
    </div>
    <div class="heroCard heroVisual"><div class="house3d"><div class="roof"></div><div class="wall"></div><div class="side"></div><div class="window"></div><div class="door"></div></div></div>
  </section>

  <section class="panel form" id="planner">
    <h2>1. Mahitaji ya mteja</h2><div class="sub">Jaza taarifa nyingi iwezekanavyo. Vipimo vipo kwa mita.</div>
    <div class="grid" style="margin-top:16px">
      <div class="field"><label>Jina la project</label><input id="project" value="Nyumba ya Familia"></div>
      <div class="field"><label>Mahali</label><input id="location" placeholder="Mfano: Dodoma, Tanzania"></div>
      <div class="field"><label>Upana wa kiwanja (m)</label><input id="plotW" type="number" step="0.1" value="20"></div>
      <div class="field"><label>Urefu wa kiwanja (m)</label><input id="plotD" type="number" step="0.1" value="30"></div>
      <div class="field"><label>Upande wa barabara</label><select id="road"><option>North</option><option>East</option><option>South</option><option>West</option></select></div>
      <div class="field"><label>Aina ya nyumba</label><select id="style"><option>Modern</option><option>Contemporary</option><option>Simple family house</option><option>Traditional Tanzanian</option></select></div>
      <div class="field full"><label>Maelekezo ya ziada</label><textarea id="notes" placeholder="Mfano: jikoni karibu na dining, master bedroom iwe private, veranda mbele, parking ya gari 2, laundry nyuma..."></textarea></div>
      <div class="field full"><label>Vyumba / spaces</label><div id="rooms" class="rooms"></div><div class="actions"><button class="secondary" type="button" onclick="addRoom()">+ Ongeza chumba</button><button class="secondary" type="button" onclick="addPreset()">Tumia family preset</button></div></div>
    </div>
    <div class="actions"><button class="primary" onclick="generatePlan()">✨ Tengeneza Ramani ya Nyumba</button><button class="secondary" onclick="document.getElementById('planner').scrollIntoView()">Anza upya</button></div>
    <div id="status" class="status"></div>
  </section>

  <section class="layout" id="results">
    <div class="panel"><button class="secondary printBtn" onclick="window.print()">🖨️ Print / PDF</button><h2>2. Ramani ya floor plan</h2><div class="sub">Vipimo na labels huonyeshwa kwenye drawing. Tumia Print/PDF kwa nakala ya awali.</div>
      <div class="tabs"><button class="tab active" onclick="showView('floor',this)">Floor Plan</button><button class="tab" onclick="showView('dimensions',this)">Dimensions</button><button class="tab" onclick="showView('inside',this)">Room View</button><button class="tab" onclick="showView('outside',this)">Outside View</button></div>
      <div class="canvas" id="drawing"><div style="padding:50px;text-align:center;color:#66798e">Jaza mahitaji kisha bonyeza <b>Tengeneza Ramani ya Nyumba</b>.</div></div>
    </div>
    <div class="viewGrid">
      <div class="info"><strong>🧭 Design summary</strong><p id="summary">Bado hakuna design.</p></div>
      <div class="info"><strong>📐 Measurements</strong><p id="measurements">Bado hakuna vipimo.</p></div>
      <div class="info"><strong>🚪 Room-to-room experience</strong><p id="experience">Baada ya ramani kutengenezwa, hapa utaona maelezo ya movement kutoka chumba kimoja kwenda kingine.</p></div>
      <div class="info"><strong>🏠 Real-world preview</strong><p id="preview">Mfumo utaeleza façade, roof, windows, doors na outdoor arrangement ya concept.</p></div>
    </div>
  </section>
  <div class="footer">Ramani Majengo — AI-assisted concept planning. © 2026</div>
</div>
<script>
let roomData=[]; let plan=null; let currentView='floor';
const defaultRooms=[['Master Bedroom',4.2,4.0],['Bedroom 2',3.6,3.5],['Bedroom 3',3.6,3.5],['Living Room',5.0,4.5],['Dining',3.5,3.2],['Kitchen',3.6,3.4],['Bathroom',2.2,2.0],['Veranda',5.5,2.0]];
function addRoom(name='Bedroom',w=3.5,d=3.5){roomData.push({name,w,d});renderRooms()}
function addPreset(){roomData=[];defaultRooms.forEach(r=>roomData.push({name:r[0],w:r[1],d:r[2]}));renderRooms()}
function removeRoom(i){roomData.splice(i,1);renderRooms()}
function renderRooms(){const el=document.getElementById('rooms');el.innerHTML=roomData.map((r,i)=>`<div class="roomLine"><input value="${esc(r.name)}" oninput="roomData[${i}].name=this.value"><input type="number" step="0.1" value="${r.w}" title="width" oninput="roomData[${i}].w=+this.value"><input type="number" step="0.1" value="${r.d}" title="depth" oninput="roomData[${i}].d=+this.value"><button class="remove" type="button" onclick="removeRoom(${i})">×</button></div>`).join('')}
function esc(s){return String(s).replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]))}
addPreset();
function payload(){return {project:document.getElementById('project').value,location:document.getElementById('location').value,plot_width:+document.getElementById('plotW').value,plot_depth:+document.getElementById('plotD').value,road_side:document.getElementById('road').value,style:document.getElementById('style').value,notes:document.getElementById('notes').value,rooms:roomData}}
async function generatePlan(){const status=document.getElementById('status');status.className='status show';status.textContent='⏳ Inatengeneza concept, mpangilio na vipimo...';try{const r=await fetch('api/generate.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload())});const data=await r.json();if(!data.ok)throw new Error(data.message||'Imeshindikana');plan=data.plan;renderPlan();status.textContent='✅ Ramani ya awali imetengenezwa. Unaweza kubadili mahitaji na kutengeneza tena.';document.getElementById('results').scrollIntoView({behavior:'smooth'})}catch(e){status.textContent='❌ '+e.message}}
function renderPlan(){document.getElementById('summary').textContent=plan.summary||'';document.getElementById('measurements').textContent=plan.measurements||'';document.getElementById('experience').textContent=plan.room_experience||'';document.getElementById('preview').textContent=plan.outside_preview||'';showView(currentView,document.querySelector('.tab.active'))}
function showView(view,btn){currentView=view;document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));if(btn)btn.classList.add('active');if(!plan)return;const el=document.getElementById('drawing');if(view==='floor'||view==='dimensions')el.innerHTML=drawFloor(view==='dimensions');else if(view==='inside')el.innerHTML=drawInside();else el.innerHTML=drawOutside()}
function scalePlan(){return 70}
function drawFloor(dims){const W=plan.house_width||14,H=plan.house_depth||12,s=scalePlan(),pad=70,vw=W*s+pad*2,vh=H*s+pad*2;let x=pad,y=pad;let cols=Math.ceil(Math.sqrt(plan.rooms.length));let rows=Math.ceil(plan.rooms.length/cols);let cw=W/cols,ch=H/rows;let cells='';plan.rooms.forEach((r,i)=>{let c=i%cols,rr=Math.floor(i/cols);let rx=x+c*cw*s,ry=y+rr*ch*s;cells+=`<g><rect x="${rx}" y="${ry}" width="${cw*s}" height="${ch*s}" fill="#fff" stroke="#111827" stroke-width="3"/><text x="${rx+cw*s/2}" y="${ry+ch*s/2-6}" text-anchor="middle" font-size="15" font-weight="700" fill="#111827">${esc(r.name)}</text><text x="${rx+cw*s/2}" y="${ry+ch*s/2+15}" text-anchor="middle" font-size="12" fill="#475569">${r.width}m × ${r.depth}m</text></g>`});let dim=`<line x1="${x}" y1="${y-28}" x2="${x+W*s}" y2="${y-28}" stroke="#111"/><text x="${x+W*s/2}" y="${y-38}" text-anchor="middle" font-size="14" font-weight="700">${W} m</text><line x1="${x-28}" y1="${y}" x2="${x-28}" y2="${y+H*s}" stroke="#111"/><text x="${x-40}" y="${y+H*s/2}" text-anchor="middle" transform="rotate(-90 ${x-40} ${y+H*s/2})" font-size="14" font-weight="700">${H} m</text>`;return `<svg viewBox="0 0 ${vw} ${vh}" xmlns="http://www.w3.org/2000/svg"><rect width="100%" height="100%" fill="white"/><text x="${vw/2}" y="25" text-anchor="middle" font-size="18" font-weight="800">${esc(plan.title||'HOUSE FLOOR PLAN')}</text>${cells}${dims}<text x="${x+W*s/2}" y="${y+H*s+38}" text-anchor="middle" font-size="13">ROAD / ${esc(payload().road_side)} SIDE</text>${dims?'<text x="20" y="'+(vh-15)+'" font-size="11">Concept drawing — verify all dimensions on site before construction.</text>':''}</svg>`}
function drawInside(){const rooms=plan.rooms||[];return `<svg viewBox="0 0 1000 650" xmlns="http://www.w3.org/2000/svg"><rect width="1000" height="650" fill="#f7f4ee"/><text x="500" y="38" text-anchor="middle" font-size="22" font-weight="800">ROOM-TO-ROOM CONCEPT VIEW</text><path d="M100 500 L900 500 L820 150 L180 150 Z" fill="#e5d7b7" stroke="#5b6570" stroke-width="4"/><path d="M180 150 L500 80 L820 150" fill="#d1c0a1" stroke="#5b6570" stroke-width="4"/><rect x="450" y="350" width="100" height="150" fill="#704b32"/><rect x="250" y="245" width="130" height="80" fill="#78c7d2" stroke="#40546a" stroke-width="7"/><rect x="620" y="245" width="130" height="80" fill="#78c7d2" stroke="#40546a" stroke-width="7"/><text x="500" y="555" text-anchor="middle" font-size="17" font-weight="700">Living / circulation → doors → private rooms</text><text x="500" y="585" text-anchor="middle" font-size="13" fill="#596a7d">${esc(plan.room_experience||'Movement path generated from the room arrangement.')}</text></svg>`}
function drawOutside(){return `<svg viewBox="0 0 1000 600" xmlns="http://www.w3.org/2000/svg"><rect width="1000" height="600" fill="#dbeafe"/><circle cx="820" cy="90" r="48" fill="#f4b942"/><rect y="430" width="1000" height="170" fill="#9ac27b"/><polygon points="180,410 500,190 820,410" fill="#334e68" stroke="#1e293b" stroke-width="5"/><polygon points="500,190 820,410 820,455 500,270" fill="#273d54"/><rect x="220" y="390" width="560" height="100" fill="#d8c9a8" stroke="#59636e" stroke-width="5"/><rect x="450" y="410" width="90" height="80" fill="#704b32"/><rect x="280" y="415" width="105" height="55" fill="#79c9d5" stroke="#40546a" stroke-width="7"/><rect x="615" y="415" width="105" height="55" fill="#79c9d5" stroke="#40546a" stroke-width="7"/><text x="500" y="535" text-anchor="middle" font-size="19" font-weight="800">${esc(plan.title||'HOUSE')} — OUTSIDE CONCEPT</text><text x="500" y="565" text-anchor="middle" font-size="13" fill="#334155">${esc(plan.outside_preview||'Front façade concept')}</text></svg>`}
</script>
</body></html>